local CoinScaleMaker = {}
local PRODUCTS = {
    iron_coin_scale = { name = "Železna tehtnica za kovance", ironCost = 4, woodCost = 2, leatherCost = 1, time = 5, cost = 185, prestige = 4, happiness = 2, description = "Železna tehtnica za tehtanje kovancev." },
    bronze_coin_scale = { name = "Bronasta tehtnica za kovance", bronzeCost = 4, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 445, prestige = 6, happiness = 3, description = "Bronasta tehtnica za precizno tehtanje." },
    silver_coin_scale = { name = "Srebrna tehtnica za kovance", silverCost = 4, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 1070, prestige = 11, happiness = 4, description = "Srebrna tehtnica za plemiške zakladnike." },
    gilded_coin_scale = { name = "Pozlačena tehtnica za kovance", goldCost = 1, silverCost = 4, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 2300, prestige = 20, happiness = 5, description = "Pozlačena tehtnica za dvorne zakladnike." },
    jewel_set_coin_scale = { name = "Draguljasta tehtnica za kovance", goldCost = 2, silverCost = 4, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4950, prestige = 36, happiness = 7, description = "Draguljasta tehtnica za kraljevske zakladnike." },
    royal_sovereign_coin_scale = { name = "Kraljevski suverena tehtnica za kovance", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 10600, prestige = 69, happiness = 13, description = "Suverena tehtnica z biseri za krono." },
}
local BUILDINGS = {
    coinscale_workshop = { name = "Tehtalna delavnica", cost = { gold = 375, wood = 180, stone = 150, iron = 9 }, upkeep = 7, qualityBonus = 5 },
    coinscale_house = { name = "Tehtalna hiša", cost = { gold = 1300, wood = 365, stone = 295, silver = 8, iron = 9 }, upkeep = 28, qualityBonus = 18 },
    master_coinscale_atelier = { name = "Mojstrski tehtalni atelje", cost = { gold = 3250, wood = 425, stone = 555, silver = 40, gold = 8 }, upkeep = 76, qualityBonus = 30 },
    sovereign_coinscale_palace = { name = "Suverena tehtalna palača", cost = { gold = 13850, wood = 660, stone = 870, gold = 89, jewel = 20 }, upkeep = 265, qualityBonus = 55, prestigeBonus = 50 },
}
CoinScaleMaker.ironStock = 16; CoinScaleMaker.bronzeStock = 14; CoinScaleMaker.woodStock = 12; CoinScaleMaker.leatherStock = 10; CoinScaleMaker.silverStock = 8; CoinScaleMaker.goldStock = 6; CoinScaleMaker.jewelStock = 4; CoinScaleMaker.pearlStock = 4
CoinScaleMaker.productStock = {}; CoinScaleMaker.buildings = {}; CoinScaleMaker.maker = nil; CoinScaleMaker.activeMaking = {}; CoinScaleMaker.totalProducts = 0; CoinScaleMaker.dayTimer = 0
function CoinScaleMaker.init() CoinScaleMaker.ironStock=16; CoinScaleMaker.bronzeStock=14; CoinScaleMaker.woodStock=12; CoinScaleMaker.leatherStock=10; CoinScaleMaker.silverStock=8; CoinScaleMaker.goldStock=6; CoinScaleMaker.jewelStock=4; CoinScaleMaker.pearlStock=4; CoinScaleMaker.productStock={}; CoinScaleMaker.buildings={}; CoinScaleMaker.maker=nil; CoinScaleMaker.activeMaking={}; CoinScaleMaker.totalProducts=0; CoinScaleMaker.dayTimer=0; print("[CoinScaleMaker] Royal Coin Scale Maker System initialized (6 products, 4 buildings)") end
function CoinScaleMaker.hireMaker(n,s) s=s or math.random(55,90); local c=590+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CoinScaleMaker.maker={name=n or ("Tehtar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Tehtar najet: %s (spretnost: %d)",CoinScaleMaker.maker.name,s),"success") end; return true end
function CoinScaleMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CoinScaleMaker.build(id) local ok,e=CoinScaleMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CoinScaleMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CoinScaleMaker.getQualityBonus() local b=0; for _,bd in ipairs(CoinScaleMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CoinScaleMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and CoinScaleMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and CoinScaleMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and CoinScaleMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and CoinScaleMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and CoinScaleMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CoinScaleMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CoinScaleMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CoinScaleMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CoinScaleMaker.buildings==0 then return false,"Potrebna tehtalna delavnica" end; if not CoinScaleMaker.maker then return false,"Potreben tehtar" end; return true end
function CoinScaleMaker.make(pt,qty) qty=qty or 1; local ok,e=CoinScaleMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then CoinScaleMaker.ironStock=CoinScaleMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then CoinScaleMaker.bronzeStock=CoinScaleMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then CoinScaleMaker.woodStock=CoinScaleMaker.woodStock-d.woodCost*qty end; if d.leatherCost then CoinScaleMaker.leatherStock=CoinScaleMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then CoinScaleMaker.silverStock=CoinScaleMaker.silverStock-d.silverCost*qty end; if d.goldCost then CoinScaleMaker.goldStock=CoinScaleMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CoinScaleMaker.jewelStock=CoinScaleMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CoinScaleMaker.pearlStock=CoinScaleMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CoinScaleMaker.maker then t=math.max(1,t-math.floor(CoinScaleMaker.maker.skill/13)) end; table.insert(CoinScaleMaker.activeMaking,{id="coinscale_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CoinScaleMaker.completeMaking(m) local q=1.0+(CoinScaleMaker.getQualityBonus()/100); if CoinScaleMaker.maker then q=q+(CoinScaleMaker.maker.skill/140) end; q=math.min(2.5,q); CoinScaleMaker.productStock[m.productType]=(CoinScaleMaker.productStock[m.productType] or 0)+m.quantity; CoinScaleMaker.totalProducts=CoinScaleMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CoinScaleMaker.maker then CoinScaleMaker.maker.itemsMade=CoinScaleMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then CoinScaleMaker.maker.skill=math.min(100,CoinScaleMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Tehtnica izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"coinscale.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function CoinScaleMaker.update(dt) if not _G.state then return end; CoinScaleMaker.dayTimer=CoinScaleMaker.dayTimer+dt; if CoinScaleMaker.dayTimer>=30 then CoinScaleMaker.dayTimer=0; for i=#CoinScaleMaker.activeMaking,1,-1 do local m=CoinScaleMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CoinScaleMaker.completeMaking(m); table.remove(CoinScaleMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CoinScaleMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CoinScaleMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CoinScaleMaker.getStats() return {ironStock=CoinScaleMaker.ironStock,bronzeStock=CoinScaleMaker.bronzeStock,woodStock=CoinScaleMaker.woodStock,leatherStock=CoinScaleMaker.leatherStock,silverStock=CoinScaleMaker.silverStock,goldStock=CoinScaleMaker.goldStock,jewelStock=CoinScaleMaker.jewelStock,pearlStock=CoinScaleMaker.pearlStock,productStock=CoinScaleMaker.productStock,numBuildings=#CoinScaleMaker.buildings,hasMaker=CoinScaleMaker.maker~=nil,makerName=CoinScaleMaker.maker and CoinScaleMaker.maker.name or "—",makerSkill=CoinScaleMaker.maker and CoinScaleMaker.maker.skill or 0,activeMaking=#CoinScaleMaker.activeMaking,totalProducts=CoinScaleMaker.totalProducts} end
return CoinScaleMaker
